#include <atomic>
#include <iostream>
#include <thread>

int payload = 0;                        // plain, non-atomic data
std::atomic<bool> ready{false};

int main() {
    std::thread producer([] {
        payload = 42;                                  // (1) plain write
        ready.store(true, std::memory_order_release);  // (2) publish
    });
    std::thread consumer([] {
        while (!ready.load(std::memory_order_acquire)) { }  // (3) acquire
        std::cout << payload << '\n';                  // (4) guaranteed 42
    });
    producer.join();
    consumer.join();
    return 0;
}

#include <atomic>
#include <iostream>
#include <thread>

class Spinlock {
    std::atomic_flag f = ATOMIC_FLAG_INIT;   // required initialiser in C++17
public:
    void lock()   { while (f.test_and_set(std::memory_order_acquire)) { } }
    void unlock() { f.clear(std::memory_order_release); }
};

Spinlock sl;
long long shared = 0;

void work(int n) {
    for (int i = 0; i < n; ++i) {
        sl.lock();
        shared += 1;                 // ordinary, non-atomic writes - safe here
        sl.unlock();
    }
}

int main() {
    std::thread a(work, 50000), b(work, 50000);
    a.join();
    b.join();
    std::cout << shared << '\n';     // 100000, every run
    return 0;
}

